// 按锁文件安装后的依赖生成可分发声明；只输出包元数据与授权正文，不写本机绝对路径。
import { execFileSync } from "node:child_process";
import { readFile, readdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
const groups = JSON.parse(
  execFileSync("pnpm", ["licenses", "list", "--prod", "--json"], {
    encoding: "utf8",
  }),
);
const packages = Object.values(groups)
  .flat()
  .sort((a, b) => a.name.localeCompare(b.name, "en"));
const sections = [
  "Cloud Agent — production dependency licenses and notices\nGenerated by pnpm licenses:generate. Do not edit manually.\nDependencies remain under their own licenses; the framework license does not replace them.",
];
for (const pkg of packages) {
  const files = [];
  for (const path of pkg.paths) {
    const names = (await readdir(path, { withFileTypes: true }))
      .filter(
        (entry) =>
          entry.isFile() &&
          /^(licen[sc]e|notice|copying)([.-]|$)/i.test(entry.name),
      )
      .map((entry) => entry.name)
      .sort();
    for (const name of names) {
      const content = (await readFile(join(path, name), "utf8"))
        .replace(/\r\n?/g, "\n")
        .split("\n")
        .map((line) => line.trimEnd())
        .join("\n");
      if (!files.some((file) => file.content === content))
        files.push({ name, content });
    }
  }
  sections.push(
    [
      `${pkg.name} @ ${pkg.versions.join(", ")}`,
      `License: ${pkg.license}`,
      ...(pkg.author
        ? [
            `Author: ${typeof pkg.author === "string" ? pkg.author : JSON.stringify(pkg.author)}`,
          ]
        : []),
      ...(pkg.homepage ? [`Upstream: ${pkg.homepage}`] : []),
      ...files.map((file) => `\n--- ${file.name} ---\n${file.content.trim()}`),
      ...(files.length
        ? []
        : [
            "No standalone license file included in the installed package; license identifier is from package metadata.",
          ]),
    ].join("\n"),
  );
}
const output =
  sections.join(
    "\n\n============================================================\n\n",
  ) + "\n";
const target = "THIRD_PARTY_NOTICES.txt";
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== output)
    throw new Error("Run pnpm licenses:generate to refresh dependency notices");
} else await writeFile(target, output);
process.stdout.write(
  `Production dependency notices: ${packages.length} packages\n`,
);
